def test_launch_gate_contract_is_evidence_bound_and_fail_closed():
 d=load('data/m262_launch_readiness_gate_contract.json'); assert d['principles']['global_launch_requires_passed_launch_readiness_gate'] is True and d['principles']['missing_evidence_never_counts_as_pass'] is True and d['principles']['test_global_evidence_isolated'] is True
 assert all(x in d['launch_critical_explicit'] for x in ['payment','account_recovery','support','moderation','backup_restore','monitoring','anti_abuse','minimum_version','rollback']); assert d['promotion']['client_may_promote_build'] is False and d['promotion']['client_may_override_blocker'] is False and d['promotion']['client_may_issue_waiver'] is False; assert all(v is False for v in d['configuration'].values())
def test_runtime_is_monotonic_ops_only_and_local_never_passes():
 s=read('scripts/online/m262_launch_readiness_runtime.gd'); assert 'if not operations_verified: return false' in s and 'incoming_revision <= revision' in s and '"RELEASE_OPS"' in s and '"state":"NOT_EVALUATED"' in s and '"production_claim":false' in s
 for token in ['can_client_promote_build','can_client_override_blocker','can_client_mark_global_ready','can_client_issue_waiver','can_client_fabricate_gate_evidence','can_client_merge_test_global_evidence','can_client_change_release_identity']: assert f'func {token}' in s
def test_command_deck_bootstrap_and_admin_integrate_without_new_main_page():
 b=read('scripts/core/game_bootstrap.gd'); d=read('scripts/ui/command_deck.gd'); c=read('scripts/ui/m262_launch_readiness_catalog.gd'); assert 'M262LaunchReadinessRuntime.new()' in b and 'LaunchReadinessGate' in b and 'LAUNCH READINESS · RELEASE CANDIDATE' in d and 'M262LaunchReadinessCatalog.overview' in d and 'Fehlende Evidenz zählt niemals als PASS' in c and 'OPS / PIPELINE ONLY' in c
 pages=d.split('var pages :=',1)[1].split('\n',1)[0]; assert 'launch_readiness' not in pages and 'release_candidate' not in pages
 a=load('data/admin_content_type_registry.json'); assert a['milestone'] in {'M262','M263','M264','M265','M266','M267','M268','M269','M270','M271','M272','M273','M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and all(x in a['content_types'] for x in ['launch_readiness_gate_definition','release_candidate_definition','release_evidence_definition','release_waiver_policy_definition'])
