 m=load('data/m239_master_convergence_matrix.json'); assert m['milestone'] in {'M262','M263','M264','M265','M266','M267','M268','M269','M270','M271','M272','M273','M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'}; row={x['domain']:x for x in m['domains']}['launch_readiness_release_candidate_verification']; assert row['status']=='PARTIAL' and 'm262_fix' in row and 'production CI/CD evidence ingestion' in row['remaining'] and 'native device/network/store/backend RC verification' in row['remaining']
